import"./chunks/assets.COeCtnMN.js";import{E as e,at as t,it as n,vt as r}from"./chunks/framework.DwjJr7zi.js";var i=JSON.parse(`{"title":"Surge Mac 如何使用不支持的协议(VLESS/SSR 等)","description":"","frontmatter":{"title":"Surge Mac 如何使用不支持的协议(VLESS/SSR 等)"},"headers":[],"relativePath":"blog/posts/1735.md","filePath":"blog/posts/1735.md","lastUpdated":1783382106000}`),a={name:`blog/posts/1735.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="surge-mac-如何使用不支持的协议-vless-ssr-等" tabindex="-1">Surge Mac 如何使用不支持的协议(VLESS/SSR 等) <a class="header-anchor" href="#surge-mac-如何使用不支持的协议-vless-ssr-等" aria-label="Permalink to “Surge Mac 如何使用不支持的协议(VLESS/SSR 等)”">​</a></h1><img class="telegram-media" src="/telegram/AQADCRJrGyiCoFd-.jpg" alt="Telegram 图片" loading="lazy" decoding="async"><div class="telegram-content"><u>Surge Mac 如何使用不支持的协议(VLESS/SSR 等)</u><br><br>⚠️ 若你不需要支援 <code>Surge</code> 本身不支持的协议<br><br>⚠️ 不要指定输出为 <code>SurgeMac</code><br><br>▎Surge for macOS 必须手动指定链接参数 <code>target=SurgeMac</code> 或在 <code>同步配置</code> 中指定 <code>SurgeMac</code> 来启用 <code>mihomo</code> 支援 <code>Surge</code> 本身不支持的协议<br><br>· 根据 <a href="https://manual.nssurge.com/policy/external-proxy.html">External Proxy Program 文档</a> <code>addresses</code> 参数要求为 IP, 可先进行 <code>节点操作</code> 中的 <code>域名解析</code><br><br>(当然你本身也可以自己在 Sub-Store 本地订阅里手写 <a href="https://manual.nssurge.com/policy/external-proxy.html">External Proxy Program</a> 格式的单行, 有时候也可能需要用不是 mihomo 的)<br><br>· 节点字段 <code>_exec</code> 为 <code>mihomo</code> 路径, 默认 <code>/usr/local/bin/mihomo</code>, 需自行下载对应平台的 <code>mihomo</code> 内核到此路径, 并设置好权限. <a href="https://t.me/zhetengsha_group/751873"><s>查看 mac 系统安装 mihomo 的喂饭命令</s></a>(已过时), 可直接使用 homebrew 安装: <code>brew install mihomo</code>. 然后使用脚本操作 <code>$server._exec = &quot;/opt/homebrew/opt/mihomo/bin/mihomo&quot;</code> 即可(如图)<br><br>· 节点字段 <code>_localPort</code> 端口为初始端口号, 逐个递减, 默认为 <code>65535</code><br><br>· <code>_merge</code> 为开启仅一个 mihomo 进程+多个 listeners 的模式, 此时仅有一个 mihomo External Proxy Program, 节点会转成 SOCKS5, <code>_mergeName</code> 可设置这个 mihomo 节点的名字(默认为 mihomo merged)<br><br>· <code>_mihomoExternal</code> 为 <code>true</code> 可强制指定使用 mihomo External Proxy Program 输出该节点<br><br>· <code>_defaultNameserver</code> (默认为 <code>[ &#39;180.76.76.76&#39;, &#39;52.80.52.52&#39;, &#39;119.28.28.28&#39;, &#39;223.6.6.6&#39; ]</code> ) 和 <code>_nameserver</code> (默认为 <code>[ &#39;https://doh.pub/dns-query&#39;, &#39;https://dns.alidns.com/dns-query&#39;, &#39;https://doh-pure.onedns.net/dns-query&#39; ]</code> ) 为数组 用于自定义 mihomo 的 <code>default-nameserver</code> 和 <code>nameserver</code><br><br>· <code>_config</code> 对象可覆盖默认配置<br><br>▎<a href="https://github.com/sub-store-org/Sub-Store/wiki/%E9%93%BE%E6%8E%A5%E5%8F%82%E6%95%B0%E8%AF%B4%E6%98%8E">链接参数说明</a><br><br>也可参考👆在链接参数上使用 <code>mihomoExternal</code>, <code>mihomoMergeName</code>, <code>mihomoMerge</code><br><br>▎排查方法<br><br>· 使用 <code>/usr/local/bin/mihomo -h</code> 进行检查, 输出有 <code>-config string specify base64-encoded configuration string</code> 即为正常.<br><br>· 查看 <code>/tmp/Surge-External-xxxxxx.log</code> 日志. <code>xxxxxx</code> 为节点名称<br><br><img class="telegram-custom-emoji" src="/telegram/AgAEDgACMozQVw.webp" alt="🤭" loading="lazy" decoding="async"> <a href="/blog/214/">Sub-Store 合集</a> <img class="telegram-custom-emoji" src="/telegram/AgADRw4AApYl0Vc.webp" alt="🧐" loading="lazy" decoding="async"> <a href="/blog/">频道资源合集</a> <img class="telegram-custom-emoji" src="/telegram/AgADmw4AArTV0Fc.webp" alt="😄" loading="lazy" decoding="async"> <a href="https://t.me/zhetengsha/957">恰饭推荐</a> <img class="telegram-custom-emoji" src="/telegram/AgAD3A4AAjTykVM.webp" alt="💬" loading="lazy" decoding="async"> <a href="https://t.me/zhetengsha_group">群组</a> <img class="telegram-custom-emoji" src="/telegram/AgADbg0AAgj82Vc.webp" alt="🥰" loading="lazy" decoding="async"><a href="https://t.me/xream_bot">联系推广</a><br><br><img class="telegram-custom-emoji" src="/telegram/AgAD_A0AAh_-0Fc.webp" alt="🥰" loading="lazy" decoding="async"> #SubStore #mihomo #Surge #SurgeMac #VLESS #SSR</div><p class="telegram-source"><a href="https://t.me/zhetengsha/1735">查看 Telegram 原文</a></p>`,4)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};